param([Parameter(Mandatory)][string]$Task,[Parameter(Mandatory)][string]$CandidatePath,[Parameter(Mandatory)][int]$PostgresPort,[Parameter(Mandatory)][int]$ApplicationPort,[Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$fixture=Join-Path $root 'fixture';$project="sensitivity-eval-$PostgresPort";$app=$null;$defects=@();try{$env:POSTGRES_PORT=$PostgresPort;&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') up -d;if($LASTEXITCODE -ne 0){throw 'postgres start'};$ready=$false;foreach($n in 1..30){&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') exec -T postgres pg_isready -U postgres -d inventory 2>$null;if($LASTEXITCODE -eq 0){$ready=$true;break};Start-Sleep 1};if(-not $ready){throw 'postgres readiness'};npm ci --ignore-scripts --silent --prefix $CandidatePath;if($LASTEXITCODE -ne 0){throw 'npm ci'};npm run build --silent --prefix $CandidatePath;if($LASTEXITCODE -ne 0){throw 'build'};$env:DATABASE_URL="postgres://postgres:postgres@127.0.0.1:$PostgresPort/inventory";$env:PORT=$ApplicationPort;$outLog=Join-Path $CandidatePath 'evaluator-app.out.log';$errLog=Join-Path $CandidatePath 'evaluator-app.err.log';$app=Start-Process node -ArgumentList 'dist/server.js' -WorkingDirectory $CandidatePath -RedirectStandardOutput $outLog -RedirectStandardError $errLog -PassThru; $healthy=$false;foreach($n in 1..30){try{if((Invoke-WebRequest "http://127.0.0.1:$ApplicationPort/health" -SkipHttpErrorCheck).StatusCode -eq 200){$healthy=$true;break}}catch{};Start-Sleep 1};if(-not $healthy){throw 'published application health failed'};Copy-Item (Join-Path $PSScriptRoot 'evaluate.mjs') (Join-Path $CandidatePath 'evaluate.mjs') -Force;$json=&node (Join-Path $CandidatePath 'evaluate.mjs') $Task $ApplicationPort|Select-Object -Last 1;$result=$json|ConvertFrom-Json}catch{$result=[ordered]@{task=$Task;primary='FAIL';confirmedDefects=@($_.Exception.Message)}}finally{if($app-and-not$app.HasExited){Stop-Process -Id $app.Id -Force};&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') down --volumes --remove-orphans 2>$null};$result|ConvertTo-Json -Depth 4|Set-Content $OutputPath;if($result.primary-ne'PASS'){exit 1}
